/// A tenant with a large account: thousands of settings, most of them not
/// webhooks, and the webhook subscriptions sorting after them.
fn large_tenant(settings: &SettingsStore, transport: &HermeticTransport, tenant: &str, host: &str) -> Vec<String> {
    for i in 0..25_000 {
        settings.put(Setting::new(tenant, &format!("member-pref/{i:05}"), "preference", json!({ "n": i })));
    }
    (1..=40)
        .map(|i| {
            let url = format!("https://{host}/hooks/{i}");
            subscribe(settings, tenant, &format!("rp-{i:02}"), &url);
            transport.route(&url, Endpoint::ok());
            url
        })
        .collect()
}

#[tokio::test(start_paused = true)]
async fn every_subscriber_of_a_large_tenant_is_notified_within_the_budget() {
    let rig = rig();
    let urls = large_tenant(&rig.settings, &rig.transport, HARBOUR, "door.harbourclub.example");

    let started = tokio::time::Instant::now();
    rig.notifier.notify(&revoked(HARBOUR, 7)).await;

    assert!(started.elapsed() < DISPATCH_BUDGET);
    for url in &urls {
        assert_eq!(rig.transport.received(url).len(), 1, "{url}");
    }
}

