async fn a_transient_failure_is_retried() {
    let rig = rig();
    let url = "https://flaky.harbourclub.example/hooks";
    subscribe(&rig.settings, HARBOUR, "rp-flaky", url);
    rig.transport.route(url, Endpoint::status(503));

