/// How long one call to a subscriber may take before it counts as failed.
pub const ATTEMPT_TIMEOUT: Duration = Duration::from_secs(3);

/// Calls made to a subscriber, at most, for one change.
pub const MAX_ATTEMPTS: u32 = 3;

