body='''pub struct Notifier {
    settings: Arc<SettingsStore>,
    transport: Arc<dyn WebhookTransport>,
    sink: Arc<dyn DeliverySink>,
    /// Subscribers to every tenant's changes.
    platform: Vec<Subscription>,
    healthy: AtomicBool,
}

impl Notifier {
    pub fn new(settings: Arc<SettingsStore>, transport: Arc<dyn WebhookTransport>, sink: Arc<dyn DeliverySink>) -> Self {
        Notifier { settings, transport, sink, platform: Vec::new(), healthy: AtomicBool::new(false) }
    }

    /// Adds a subscriber to every tenant's changes.
    pub fn with_platform_subscriber(mut self, subscription: Subscription) -> Self {
        self.platform.push(subscription);
        self
    }

    /// Whether the most recent change was delivered to every one of its
    /// subscribers. `false` until a change has been sent.
    pub fn healthy(&self) -> bool {
        self.healthy.load(Ordering::SeqCst)
    }

    /// Sends `change` to the platform subscribers and to every subscriber of
    /// the issuing tenant, all at once, and returns once each has an outcome
    /// or the [`DISPATCH_BUDGET`] is spent.
    pub async fn notify(&self, change: &StatusChange) {
        let deadline = Instant::now() + DISPATCH_BUDGET;
        let tenant = change.issuer.as_str();
        let body: Arc<[u8]> = payload(change).into();

        let Ok(tenant_subscriptions) = tokio::time::timeout_at(deadline, self.subscriptions(tenant)).await else {
            eprintln!("notifier: {tenant}: looking up subscriptions for {} did not finish within {DISPATCH_BUDGET:?}", change.credential_id);
            self.healthy.store(false, Ordering::SeqCst);
            return;
        };

        let mut deliveries = JoinSet::new();
        for sub in self.platform.iter().cloned().chain(tenant_subscriptions) {
            let transport = self.transport.clone();
            let sink = self.sink.clone();
            let tenant = tenant.to_string();
            let body = body.clone();
            deliveries.spawn(async move { deliver(&*transport, &*sink, &tenant, &sub, &body, deadline).await });
        }

        let mut all_delivered = true;
        while let Some(result) = deliveries.join_next().await {
            all_delivered &= result.unwrap_or(false);
        }
        self.healthy.store(all_delivered, Ordering::SeqCst);
    }

    /// The tenant's webhook subscriptions, through the `tenant-kind` index,
    /// so the cost depends on how many webhooks the tenant has rather than
    /// on how many settings.
    async fn subscriptions(&self, tenant: &str) -> Vec<Subscription> {
        self.settings.query_kind(tenant, WEBHOOK_KIND).await.iter().filter_map(Subscription::from_setting).collect()
    }
}

/// POSTs `body` to `sub`, retrying transient failures until [`MAX_ATTEMPTS`]
/// or `deadline`, and reports the final outcome; `true` if delivered.
async fn deliver(
    transport: &dyn WebhookTransport,
    sink: &dyn DeliverySink,
    tenant: &str,
    sub: &Subscription,
    body: &[u8],
    deadline: Instant,
) -> bool {
    let mut backoff = RETRY_BACKOFF;
    let mut attempt = 1;
    let outcome = loop {
        let attempt_deadline = (Instant::now() + ATTEMPT_TIMEOUT).min(deadline);
        let response = match tokio::time::timeout_at(attempt_deadline, transport.post(&sub.url, body)).await {
            Ok(response) => response,
            Err(_) => Err(crate::webhook::WebhookError::Unreachable(format!("{} (no answer in time)", sub.url))),
        };
        let outcome = match &response {
            Ok(status) if (200..300).contains(status) => Outcome::Delivered { status: *status },
            Ok(status) => Outcome::Failed { reason: format!("HTTP {status}") },
            Err(error) => Outcome::Failed { reason: error.to_string() },
        };
        if !outcome.retryable(&response) || attempt >= MAX_ATTEMPTS || Instant::now() + backoff >= deadline {
            break match outcome {
                Outcome::Failed { reason } if attempt > 1 => Outcome::Failed { reason: format!("{reason} (after {attempt} attempts)") },
                outcome => outcome,
            };
        }
        tokio::time::sleep(backoff).await;
        backoff *= 2;
        attempt += 1;
    };
    let delivered = matches!(outcome, Outcome::Delivered { .. });
    sink.record(DeliveryEvent { tenant: tenant.to_string(), subscription: sub.id.clone(), outcome });
    delivered
}
